"""Mandelbrot escape times computed on the GPU, summarized on standard output.

Usage: uv run main.py <parameter-file>

The parameter file holds two lines:
    <width> <height> <limit>
    <x_min> <x_max> <y_min> <y_max>
"""

import struct
import sys
from pathlib import Path

import numpy as np
import wgpu

WORKGROUP = 16

# Upper bound on point-iterations submitted in one GPU command buffer, so a
# single dispatch never runs long enough to hit a driver watchdog timeout.
WORK_PER_SUBMIT = 1 << 27

# One invocation per grid point. Coordinates follow the contract; the escape
# loop is a direct transcription of the one given there.
SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    row0: u32,
    rows: u32,
    x0: f32,
    dx: f32,
    y0: f32,
    dy: f32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> escape: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= p.width || gid.y >= p.rows) {
        return;
    }
    let j = p.row0 + gid.y;
    let cx = p.x0 + f32(i) * p.dx;
    let cy = p.y0 + f32(j) * p.dy;

    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    while (n < p.limit && zx * zx + zy * zy <= 4.0) {
        let nx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nx;
        n = n + 1u;
    }
    escape[j * p.width + i] = n;
}
"""


def read_parameters(path):
    tokens = Path(path).read_text().split()
    width, height, limit = (int(t) for t in tokens[0:3])
    x_min, x_max, y_min, y_max = (float(t) for t in tokens[3:7])
    return width, height, limit, x_min, x_max, y_min, y_max


def compute_escape_times(width, height, limit, x_min, x_max, y_min, y_max):
    """Return a (height, width) array of escape times, computed on the GPU."""
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )

    # Grid geometry in double precision, handed to the GPU as single precision:
    # column i sits at x0 + i * dx and row j at y0 + j * dy.
    dx = (x_max - x_min) / width
    dy = (y_max - y_min) / height
    x0 = x_min + 0.5 * dx
    y0 = y_min + 0.5 * dy

    params = device.create_buffer(
        size=36, usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST
    )
    out = device.create_buffer(
        size=width * height * 4,
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": 36}},
            {"binding": 1, "resource": {"buffer": out, "offset": 0, "size": out.size}},
        ],
    )

    rows_per_submit = max(1, WORK_PER_SUBMIT // (width * limit))
    for row0 in range(0, height, rows_per_submit):
        rows = min(rows_per_submit, height - row0)
        device.queue.write_buffer(
            params,
            0,
            struct.pack(
                "<5I4f",
                width, height, limit, row0, rows,
                x0, dx, y0, dy,
            ),
        )
        encoder = device.create_command_encoder()
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_group)
        compute.dispatch_workgroups(
            (width + WORKGROUP - 1) // WORKGROUP,
            (rows + WORKGROUP - 1) // WORKGROUP,
            1,
        )
        compute.end()
        device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(out)
    return np.frombuffer(data, dtype=np.uint32).reshape(height, width).copy()


def summarize(escape, limit):
    inside = escape == limit
    escaped = escape[~inside].astype(np.int64)

    inside_count = int(np.count_nonzero(inside))
    bins = np.bincount((8 * escaped) // limit, minlength=8)[:8]
    if escaped.size:
        mean = float(escaped.sum(dtype=np.float64)) / escaped.size
    else:
        mean = 0.0

    lines = [f"INSIDE {inside_count}"]
    lines += [f"BIN {b} {int(bins[b])}" for b in range(8)]
    lines.append(f"MEAN {mean:.3f}")
    return lines


def main():
    if len(sys.argv) != 2:
        print("usage: main.py <parameter-file>", file=sys.stderr)
        return 2

    width, height, limit, x_min, x_max, y_min, y_max = read_parameters(sys.argv[1])
    escape = compute_escape_times(width, height, limit, x_min, x_max, y_min, y_max)
    for line in summarize(escape, limit):
        sys.stdout.write(line + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

